async function captureAll(tab, outputDir) {
  return await tab.run(async ({ page, tab, assert }, outputDir) => {
    const fs = await import('node:fs/promises');
    await fs.mkdir(outputDir, { recursive: true });
    await page.setViewport({ width: 1440, height: 900, deviceScaleFactor: 1.25 });
    const records = [];
    const errors = [];
    page.on('pageerror', e => errors.push(String(e)));
    const click = async selector => { await page.click(selector); };
    const fill = async (selector, value) => {
      await tab.fill(selector, value);
    };
    const check = async (label, expression) => {
      const value = await tab.evaluate(`(${expression.toString()})()`);
      assert(value, label);
      records.push({ check: label, passed: true });
    };
    const shot = async name => {
      await page.mouse.move(1400, 850);
      await page.screenshot({ path: `${outputDir}/${name}.png` });
      records.push({ screenshot: `${name}.png` });
    };
    await page.goto('http://127.0.0.1:48431/?kind=Pod');
    await page.waitForSelector('#name');
    await check('Pod starts in Form mode with blank required fields', () => window.__mock.state.kind === 'Pod' && window.__mock.state.mode === 'form' && document.querySelector('#name').value === '' && document.querySelector('#image').value === '');
    await shot('01-pod-empty-form');
    await click('#review');
    await check('Required fields show inline errors', () => document.querySelectorAll('[aria-invalid=true]').length === 2 && !window.__mock.state.review);
    await shot('02-pod-inline-validation');
    await fill('#name', 'debug-shell');
    await fill('#image', 'nginx:1.27.3');
    await fill('#port', '8080');
    await click('[data-mode="yaml"]');
    await click('[data-mode="form"]');
    await page.hover('[data-help="port"]');
    await check('Container-port help opens on hover', () => window.__mock.state.help === 'port' && document.querySelector('.tooltip').textContent.includes('does not expose'));
    await page.mouse.move(1400, 850);
    await page.focus('[data-help="port"]');
    await tab.evaluate('new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))');
    await page.screenshot({ path: `${outputDir}/03-pod-contextual-help.png` });
    records.push({ screenshot: '03-pod-contextual-help.png' });
    await click('[data-section="Containers"]');
    await fill('[data-key="cpuRequest"]', '250');
    await fill('[data-key="cpuLimit"]', '1000');
    await fill('[data-key="memRequest"]', '256');
    await fill('[data-key="memLimit"]', '512');
    await click('#add-env');
    await fill('[data-env="0:key"]', 'LOG_LEVEL');
    await fill('[data-env="0:value"]', 'info');
    await click('#add-env');
    await fill('[data-env="1:key"]', 'HTTP_PORT');
    await fill('[data-env="1:value"]', '8080');
    await check('Repeatable environment rows retain entered values', () => window.__mock.state.draft.env[0].key === 'LOG_LEVEL' && window.__mock.state.draft.env[1].value === '8080');
    await shot('04-pod-container-resources');
    await click('[data-section="Basics"]');
    await click('[data-mode="yaml"]');
    await check('YAML retains form values after section navigation', () => document.querySelector('textarea').value.includes('cpu: 250m') && document.querySelector('textarea').value.includes('containerPort: 8080') && document.querySelector('textarea').value.includes('LOG_LEVEL'));
    await shot('05-pod-yaml-mode');
    await click('[data-mode="form"]');
    await click('#review');
    await check('Review retains draft destination and image', () => window.__mock.state.review && document.querySelector('.review').textContent.includes('nginx:1.27.3') && document.querySelector('.review').textContent.includes('dev-us-east / payments'));
    await click('#back');
    await click('[data-mode="yaml"]');
    await page.click('textarea');
    await page.keyboard.press('End');
    await page.keyboard.type('\n# custom YAML edit');
    await click('[data-mode="form"]');
    await check('Edited YAML cannot be silently overwritten by Form', () => window.__mock.state.yamlEdited && document.querySelector('fieldset').disabled && window.__mock.state.yaml.includes('# custom YAML edit'));
    await click('[data-mode="yaml"]');
    await check('Raw YAML edit remains intact after mode switches', () => document.querySelector('textarea').value.includes('# custom YAML edit'));
    await page.goto('http://127.0.0.1:48431/?kind=Deployment');
    await page.waitForSelector('#name');
    await fill('#name', 'payments-api');
    await fill('#image', 'ghcr.io/acme/payments-api:2.8.0');
    await fill('#port', '8080');
    await fill('#replicas', '3');
    await click('#labels-toggle');
    await check('Deployment has replicas and linked selector preview', () => document.querySelector('#replicas').value === '3' && document.querySelector('.hint-chip').textContent.includes('Selector + Pod label linked'));
    await shot('06-deployment-form');
    await page.goto('http://127.0.0.1:48431/?kind=StatefulSet');
    await page.waitForSelector('#name');
    await fill('#name', 'postgres');
    await fill('#image', 'postgres:17.2');
    await fill('#port', '5432');
    await page.select('#service', 'postgres-headless');
    await check('StatefulSet exposes governing Service instead of Deployment strategy', () => document.querySelector('#service').value === 'postgres-headless' && !document.querySelector('#strategy'));
    await shot('07-statefulset-form');
    await click('[data-section="Storage"]');
    await fill('#storage', '20');
    await fill('#mount', '/var/lib/postgresql/data');
    await check('Per-replica storage computes total request', () => document.querySelector('.hint-chip').textContent.includes('3 claims × 20 Gi = 60 Gi'));
    await shot('08-statefulset-storage');
    await page.hover('[data-help="storage"]');
    await check('Storage lifecycle consequence stays in contextual help', () => document.querySelector('.tooltip').textContent.includes('Claims can remain'));
    await tab.evaluate('new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)))');
    await page.screenshot({ path: `${outputDir}/09-statefulset-storage-help.png` });
    records.push({ screenshot: '09-statefulset-storage-help.png' });
    await click('[data-section="Basics"]');
    await click('[data-mode="yaml"]');
    await check('Storage remains in YAML after leaving Storage section', () => document.querySelector('textarea').value.includes('volumeClaimTemplates:') && document.querySelector('textarea').value.includes('storage: 20Gi') && document.querySelector('textarea').value.includes('serviceName: postgres-headless'));
    await click('[data-mode="form"]');
    await page.focus('[data-help="service"]');
    await check('Contextual help works with keyboard focus', () => window.__mock.state.help === 'service');
    await page.keyboard.press('Escape');
    await check('Escape dismisses help without closing modal', () => window.__mock.state.help === null && window.__mock.state.open);
    await page.keyboard.press('Escape');
    await check('Escape closes dialog and restores opener focus', () => !window.__mock.state.open && document.activeElement.id === 'launch');
    await click('#launch');
    await check('Create button reopens draft', () => window.__mock.state.open && document.querySelector('#name').value === 'postgres');
    assert(errors.length === 0, `No page errors: ${errors.join('; ')}`);
    await fs.writeFile(`${outputDir}/checks.json`, JSON.stringify({ viewport: '1440x900 @1.25', records, errors }, null, 2));
    return { records, errors };
  }, { args: [outputDir], timeout: 120 });
}
